-- 239_rollback.sql (restores 236's description, captured from the live row)
begin;
update events set description = 'Calling all future Mavericks! Elementary and middle school students who will attend McNeil High School are invited to run out of the tunnel with the team to kick off the Homecoming game vs Round Rock. The school with the most students registered takes home the Homecoming Tunnel Stampede trophy and bragging rights for the year. Participants arrive at 6:00 PM at the HOME side ticket booth to check in and pick up their Tunnel Stampede t-shirt and a wristband. At 6:30 PM JV players group them by grade and walk them to the tunnel, and the Stampede runs at 6:40 PM. Parents drop off and sit in the Tunnel Stampede bleachers on the HOME side, then meet their student at the home ticket booth end of the field after the trophy presentation, where booster club members match wristbands. Registration includes the participant''s t-shirt and a game ticket. Parent game tickets are NOT included; buy them in advance from Round Rock ISD Athletics. Every child who wants a t-shirt needs to register, even if they do not plan to run.', updated_at = now() where slug = 'homecoming-tunnel-stampede-2026';
commit;
